/* ProfessionUI_Module.js - 武装工坊组件 (JS 模块版) */

const ProfessionStyles = `
  .prof-module-scope {
    --panel: rgba(8, 26, 36, 0.34);
    --panel-strong: rgba(12, 35, 47, 0.48);
    --line: rgba(150, 217, 228, 0.22);
    --line-soft: rgba(150, 217, 228, 0.09);
    --cyan: #8de1ef;
    --cyan-soft: rgba(141, 225, 239, 0.14);
    --gold: #e2c866;
    --gold-soft: rgba(226, 200, 102, 0.14);
    --red: #ff8aa2;
    --green: #7dffb2;
    --text: #e4f5f9;
    --text-sub: #bfdde4;
    --text-dim: #87aeb7;
    --font-tech: 'Orbitron', sans-serif;
    --font-cjk: 'Noto Serif SC', serif;
    --prof-font-base: 10.5px;

    width: 100%;
    color: var(--text);
    font-family: var(--font-cjk);
    font-size: var(--prof-font-base);
    line-height: 1.35;
    display: flex;
    flex-direction: column;
    gap: 12px;
  }

  .prof-module-scope .top-status {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 8px;
  }

  .prof-module-scope .status-chip {
    position: relative;
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    grid-template-areas:
      "icon label"
      "icon value"
      "bar bar";
    gap: 3px 8px;
    min-width: 0;
    padding: 8px 9px;
    border: 1px solid rgba(141, 225, 239, 0.1);
    border-radius: 7px;
    background:
      linear-gradient(180deg, rgba(141, 225, 239, 0.055), rgba(0, 0, 0, 0.1)),
      rgba(3, 12, 18, 0.28);
    box-shadow: inset 0 0 12px rgba(0, 0, 0, 0.18);
  }

  .prof-module-scope .status-chip::before {
    content: '';
    grid-area: icon;
    align-self: center;
    width: 8px;
    height: 18px;
    border-radius: 999px;
    background: var(--status-color, var(--cyan));
    box-shadow: 0 0 12px rgba(141, 225, 239, 0.2);
  }

  .prof-module-scope .chip-label {
    grid-area: label;
    font-size: 0.86em;
    color: var(--text-dim);
    text-transform: uppercase;
    letter-spacing: 0;
  }

  .prof-module-scope .chip-value {
    grid-area: value;
    font-family: var(--font-tech);
    font-size: 1em;
    line-height: 1.1;
    color: var(--status-color, var(--gold));
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    word-break: break-all;
  }

  .prof-module-scope .chip-bar {
    grid-area: bar;
    height: 3px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.055);
    overflow: hidden;
  }

  .prof-module-scope .chip-bar-fill {
    display: block;
    width: 0%;
    height: 100%;
    border-radius: inherit;
    background: linear-gradient(90deg, rgba(255, 255, 255, 0.18), var(--status-color, var(--cyan)));
    box-shadow: 0 0 10px rgba(141, 225, 239, 0.18);
    transition: width 0.2s ease;
  }

  .prof-module-scope .status-chip--vital { --status-color: #ff8aa2; }
  .prof-module-scope .status-chip--soul { --status-color: #8de1ef; }
  .prof-module-scope .status-chip--mind { --status-color: #d9c86f; }

  .prof-module-scope .tabs {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 3px;
    padding: 3px;
    border: 1px solid rgba(141, 225, 239, 0.1);
    border-radius: 8px;
    background: rgba(0, 0, 0, 0.24);
    box-shadow: inset 0 0 16px rgba(0, 0, 0, 0.22);
  }

  .prof-module-scope .tab-btn {
    border: 1px solid transparent;
    background: transparent;
    color: var(--text-dim);
    border-radius: 6px;
    padding: 7px 4px;
    cursor: pointer;
    font-size: 0.95em;
    font-weight: 700;
    letter-spacing: 0;
    transition: 0.2s ease;
  }

  .prof-module-scope .tab-btn.active {
    color: var(--cyan);
    border-color: rgba(141, 225, 239, 0.42);
    background:
      linear-gradient(180deg, rgba(141, 225, 239, 0.18), rgba(141, 225, 239, 0.055)),
      rgba(8, 28, 38, 0.72);
    box-shadow:
      0 0 16px rgba(141, 225, 239, 0.13),
      inset 0 1px 0 rgba(255, 255, 255, 0.16);
  }

  .prof-module-scope .prof-workshop-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.56fr) minmax(300px, 0.92fr);
    gap: 12px;
    align-items: stretch;
  }

  .prof-module-scope .prof-workshop-left,
  .prof-module-scope .prof-workshop-right {
    min-width: 0;
  }

  .prof-module-scope .prof-workshop-right {
    position: sticky;
    top: 8px;
    display: grid;
    grid-template-rows: minmax(0, 1fr) auto;
    gap: 9px;
    align-self: start;
  }

  .prof-module-scope .section-card {
    position: relative;
    background: linear-gradient(180deg, rgba(141, 225, 239, 0.045), rgba(0, 0, 0, 0.08));
    border: 0;
    border-radius: 6px;
    padding: 10px;
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.035);
  }

  .prof-module-scope .section-card--process {
    display: grid;
    gap: 10px;
    box-shadow:
      inset 0 0 0 1px rgba(141, 225, 239, 0.055),
      inset 0 18px 36px rgba(0, 0, 0, 0.12);
  }

  .prof-module-scope .section-card--preview {
    display: grid;
    gap: 10px;
    border: 1px solid rgba(141, 225, 239, 0.12);
    background:
      radial-gradient(circle at 50% 0%, rgba(226, 200, 102, 0.07), transparent 42%),
      linear-gradient(180deg, rgba(13, 42, 55, 0.46), rgba(4, 15, 22, 0.28));
    box-shadow:
      0 12px 28px rgba(0, 0, 0, 0.18),
      inset 0 1px 0 rgba(255, 255, 255, 0.05);
  }

  .prof-module-scope .section-title {
    display: flex;
    align-items: center;
    gap: 8px;
    min-width: 0;
    font-family: var(--font-title);
    font-size: 1.16em;
    line-height: 1.2;
    color: var(--white);
    font-weight: 700;
    margin-bottom: 0;
    letter-spacing: 0;
    text-transform: none;
    text-shadow: 0 1px 0 rgba(255,255,255,0.05), 0 0 6px rgba(77,240,255,0.08);
  }

  .prof-module-scope .section-title::before {
    content: '◈';
    font-size: 0.78em;
    color: var(--cyan);
    flex: 0 0 auto;
  }

  .prof-module-scope .section-title::after {
    content: '';
    flex: 1;
    min-width: 28px;
    height: 1px;
    background: linear-gradient(90deg, rgba(103,247,239,0.38), rgba(255,226,89,0.16), transparent);
    opacity: 0.78;
  }

  .prof-module-scope .prof-command-head {
    display: grid;
    gap: 3px;
  }

  .prof-module-scope .prof-command-subtitle,
  .prof-module-scope .hint {
    font-size: 0.9em;
    color: var(--text-dim);
    line-height: 1.35;
  }

  .prof-module-scope .prof-command-line {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: 10px;
    min-width: 0;
  }

  .prof-module-scope .prof-config-grid {
    display: grid;
    grid-template-columns: minmax(150px, 1.2fr) repeat(3, minmax(96px, 0.72fr));
    gap: 8px;
    min-width: 0;
    align-items: end;
  }

  .prof-module-scope .form-group {
    min-width: 0;
    margin-bottom: 0;
  }

  .prof-module-scope .form-group label {
    display: block;
    margin-bottom: 3px;
    font-size: 0.82em;
    color: rgba(191, 221, 228, 0.68);
    text-transform: uppercase;
    font-weight: 700;
    letter-spacing: 0;
    white-space: nowrap;
  }

  .prof-module-scope .param-token {
    min-width: 0;
  }

  .prof-module-scope .param-token--target,
  .prof-module-scope .param-token--materials {
    min-width: 0;
  }

  .prof-module-scope .prof-input-shell {
    display: grid;
    gap: 6px;
  }

  .prof-module-scope .tech-select, .prof-module-scope .tech-input {
    width: 100%;
    min-height: 25px;
    background:
      linear-gradient(180deg, rgba(255, 255, 255, 0.045), rgba(0, 0, 0, 0.18)),
      rgba(3, 13, 19, 0.5);
    border: 1px solid rgba(141, 225, 239, 0.13);
    color: var(--cyan);
    padding: 6px 8px;
    border-radius: 6px;
    font-family: var(--font-cjk);
    font-size: 1em;
    font-weight: 760;
    outline: none;
    transition: border-color 0.2s, box-shadow 0.2s, color 0.2s;
    box-sizing: border-box;
  }
  .prof-module-scope .tech-select:focus, .prof-module-scope .tech-input:focus {
    border-color: rgba(141, 225, 239, 0.62);
    color: #f7fcff;
    box-shadow:
      0 0 0 1px rgba(141, 225, 239, 0.16),
      inset 0 0 16px rgba(141, 225, 239, 0.08);
  }
  .prof-module-scope .tech-select option { background: #1a2a32; color: var(--text); }

  .prof-module-scope .prof-blueprint-node {
    position: relative;
    min-height: 38px;
    display: grid;
    grid-template-columns: 18px minmax(0, 1fr);
    place-items: center start;
    gap: 8px;
    overflow: hidden;
    border-radius: 7px;
    border: 1px dashed rgba(141, 225, 239, 0.16);
    background:
      linear-gradient(rgba(141, 225, 239, 0.045) 1px, transparent 1px),
      linear-gradient(90deg, rgba(141, 225, 239, 0.04) 1px, transparent 1px),
      rgba(2, 10, 15, 0.34);
    background-size: 10px 10px;
    color: rgba(135, 174, 183, 0.72);
    font-size: 0.9em;
    letter-spacing: 0;
    text-align: left;
    padding: 7px 10px;
    box-shadow: inset 0 0 18px rgba(0, 0, 0, 0.24);
  }

  .prof-module-scope .prof-blueprint-node::before {
    content: '';
    width: 13px;
    height: 18px;
    border: 1px solid currentColor;
    clip-path: polygon(50% 0, 100% 32%, 78% 100%, 22% 100%, 0 32%);
    opacity: 0.5;
    filter: drop-shadow(0 0 8px rgba(141, 225, 239, 0.12));
  }

  .prof-module-scope .prof-blueprint-node span {
    position: static;
    min-width: 0;
    width: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .prof-module-scope .prof-blueprint-node.is-ready {
    border-style: solid;
    border-color: rgba(141, 225, 239, 0.48);
    color: var(--cyan);
    background:
      linear-gradient(rgba(141, 225, 239, 0.07) 1px, transparent 1px),
      linear-gradient(90deg, rgba(141, 225, 239, 0.055) 1px, transparent 1px),
      radial-gradient(circle at 50% 8%, rgba(141, 225, 239, 0.22), transparent 48%),
      rgba(3, 18, 26, 0.46);
    box-shadow:
      inset 0 0 18px rgba(141, 225, 239, 0.08),
      0 0 18px rgba(141, 225, 239, 0.12);
  }

  .prof-module-scope .metal-list-container {
    max-height: 208px;
    overflow-y: auto;
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(118px, 1fr));
    gap: 8px;
    padding: 8px;
    background:
      radial-gradient(circle at 50% 0%, rgba(141, 225, 239, 0.06), transparent 52%),
      rgba(0, 0, 0, 0.16);
    border: 1px solid rgba(141, 225, 239, 0.11);
    border-radius: 8px;
    box-shadow: inset 0 0 18px rgba(0, 0, 0, 0.22);
    scrollbar-width: thin;
  }

  .prof-module-scope .material-item {
    position: relative;
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    grid-template-rows: auto auto;
    gap: 3px 7px;
    cursor: pointer;
    color: var(--text);
    min-width: 0;
    min-height: 60px;
    padding: 8px;
    border-radius: 7px;
    border: 1px solid rgba(141, 225, 239, 0.14);
    background:
      linear-gradient(180deg, rgba(141, 225, 239, 0.055), rgba(0, 0, 0, 0.14)),
      rgba(4, 14, 21, 0.44);
    font-size: 0.95em;
    line-height: 1.25;
    overflow: hidden;
    box-shadow:
      inset 0 0 0 1px rgba(255, 255, 255, 0.025),
      inset 0 -12px 24px rgba(0, 0, 0, 0.14);
    transition: border-color 0.18s ease, background 0.18s ease, box-shadow 0.18s ease;
  }

  .prof-module-scope .material-item:hover,
  .prof-module-scope .material-item.is-selected {
    border-color: rgba(141, 225, 239, 0.48);
    background:
      radial-gradient(circle at 50% 0%, rgba(141, 225, 239, 0.16), transparent 54%),
      rgba(5, 21, 30, 0.58);
    box-shadow:
      inset 0 0 18px rgba(141, 225, 239, 0.08),
      0 0 16px rgba(141, 225, 239, 0.1);
  }

  .prof-module-scope .material-item input {
    flex: 0 0 auto;
    grid-row: 1 / span 2;
    align-self: start;
    margin: 0;
    accent-color: var(--cyan);
  }

  .prof-module-scope .material-name,
  .prof-module-scope .material-meta {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .prof-module-scope .material-name {
    color: var(--text);
    font-weight: 760;
  }

  .prof-module-scope .material-meta {
    color: var(--text-dim);
    font-family: var(--font-tech);
    font-size: 0.82em;
  }

  .prof-module-scope .prof-empty-slots {
    grid-column: 1 / -1;
    display: grid;
    grid-template-columns: repeat(5, minmax(42px, 1fr));
    gap: 8px;
    align-items: stretch;
  }

  .prof-module-scope .prof-empty-slot {
    position: relative;
    min-height: 58px;
    border-radius: 8px;
    border: 1px dashed rgba(141, 225, 239, 0.17);
    background: rgba(0, 0, 0, 0.2);
    box-shadow:
      inset 0 0 18px rgba(0, 0, 0, 0.32),
      inset 0 0 0 1px rgba(255, 255, 255, 0.02);
  }

  .prof-module-scope .prof-empty-slot::before,
  .prof-module-scope .prof-empty-slot::after {
    content: '';
    position: absolute;
    left: 50%;
    top: 50%;
    border-radius: 999px;
    background: rgba(141, 225, 239, 0.18);
    transform: translate(-50%, -50%);
  }

  .prof-module-scope .prof-empty-slot::before {
    width: 18px;
    height: 2px;
  }

  .prof-module-scope .prof-empty-slot::after {
    width: 2px;
    height: 18px;
  }

  .prof-module-scope .prof-empty-copy {
    grid-column: 1 / -1;
    display: grid;
    place-items: center;
    min-height: 30px;
    color: rgba(135, 174, 183, 0.74);
    font-size: 0.95em;
    letter-spacing: 0;
  }

  .prof-module-scope .hint {
    margin-top: 4px;
  }

  .prof-module-scope .prof-info-alert {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    gap: 7px;
    align-items: start;
    padding: 7px 8px;
    border-radius: 7px;
    border: 1px solid rgba(141, 225, 239, 0.09);
    background: rgba(141, 225, 239, 0.045);
    color: rgba(191, 221, 228, 0.78);
    font-size: 0.9em;
    line-height: 1.35;
  }

  .prof-module-scope .prof-workshop-tips {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 7px;
    min-width: 0;
    padding-top: 2px;
  }

  .prof-module-scope .prof-workshop-tip-title {
    grid-column: 1 / -1;
    color: rgba(191, 221, 228, 0.72);
    font-size: 0.82em;
    font-weight: 760;
    letter-spacing: 0;
  }

  .prof-module-scope .prof-info-alert::before {
    content: 'i';
    display: grid;
    place-items: center;
    width: 15px;
    height: 15px;
    border-radius: 50%;
    border: 1px solid rgba(141, 225, 239, 0.28);
    color: var(--cyan);
    font-family: var(--font-tech);
    font-size: 0.9em;
    font-style: normal;
  }

  .prof-module-scope .info-panel {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: 9px;
    background: transparent;
    border: 0;
    border-radius: 0;
    padding: 0;
    font-size: 0.95em;
    color: var(--text-sub);
    line-height: 1.3;
  }

  .prof-module-scope .prof-preview-summary,
  .prof-module-scope .prof-preview-hero,
  .prof-module-scope .prof-resource-compare,
  .prof-module-scope .prof-preview-detail-list {
    display: grid;
    min-width: 0;
  }

  .prof-module-scope .prof-preview-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
    padding-bottom: 8px;
    border-bottom: 1px solid rgba(141, 225, 239, 0.1);
  }

  .prof-module-scope .prof-preview-hero {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
  }

  .prof-module-scope .prof-resource-compare {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
    padding: 8px 0;
    border-top: 1px solid rgba(141, 225, 239, 0.09);
    border-bottom: 1px solid rgba(141, 225, 239, 0.09);
  }

  .prof-module-scope .prof-preview-detail-list {
    gap: 0;
  }

  .prof-module-scope .info-row {
    display: grid;
    grid-template-columns: minmax(82px, 0.36fr) minmax(0, 1fr);
    gap: 8px;
    align-items: baseline;
    min-width: 0;
    min-height: 0;
    padding: 7px 0;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: inset 0 -1px 0 rgba(141, 225, 239, 0.07);
  }

  .prof-module-scope .info-row--wide {
    grid-column: 1 / -1;
  }

  .prof-module-scope .info-row--subtle {
    min-height: 0;
    background: transparent;
    box-shadow: inset 0 -1px 0 rgba(141, 225, 239, 0.08);
  }

  .prof-module-scope .info-row--resource {
    grid-template-columns: minmax(0, 1fr);
    gap: 2px;
  }

  .prof-module-scope .info-row--hero {
    grid-template-columns: minmax(0, 1fr);
    align-items: start;
    min-height: 82px;
    padding: 10px 11px;
    border-radius: 7px;
    border: 1px solid rgba(141, 225, 239, 0.13);
    background:
      radial-gradient(circle at 50% 0%, rgba(141, 225, 239, 0.1), transparent 58%),
      rgba(2, 12, 18, 0.34);
  }

  .prof-module-scope .info-row--hero .info-val {
    font-family: var(--font-tech);
    font-size: 1.72em;
    line-height: 1.2;
    color: var(--gold);
    overflow: visible;
    text-overflow: clip;
    white-space: normal;
    overflow-wrap: anywhere;
  }

  .prof-module-scope .info-row--rate .info-val.rate-safe {
    color: var(--green);
    text-shadow: 0 0 12px rgba(125, 255, 178, 0.18);
  }

  .prof-module-scope .info-row--rate .info-val.rate-warn {
    color: var(--gold);
    text-shadow: 0 0 12px rgba(226, 200, 102, 0.18);
  }

  .prof-module-scope .info-row--rate .info-val.rate-danger {
    color: var(--red);
    text-shadow: 0 0 12px rgba(255, 138, 162, 0.18);
  }

  .prof-module-scope .info-key {
    color: var(--text-dim);
    min-width: 0;
    font-size: 0.82em;
    line-height: 1;
    white-space: nowrap;
  }
  .prof-module-scope .info-val {
    color: var(--text);
    min-width: 0;
    overflow: hidden;
    text-align: left;
    text-overflow: ellipsis;
    white-space: nowrap;
    word-break: normal;
  }

  .prof-module-scope .info-row--note .info-val,
  .prof-module-scope .info-row--loop .info-val {
    white-space: normal;
    display: block;
    overflow: visible;
  }

  .prof-module-scope .prof-loop-tokens {
    display: flex;
    flex-wrap: wrap;
    gap: 5px;
    min-width: 0;
  }

  .prof-module-scope .prof-loop-token {
    display: inline-flex;
    align-items: baseline;
    gap: 4px;
    max-width: 100%;
    padding: 3px 7px;
    border-radius: 999px;
    border: 1px solid rgba(141, 225, 239, 0.1);
    background: rgba(141, 225, 239, 0.045);
    color: var(--text-sub);
    line-height: 1.2;
  }

  .prof-module-scope .prof-loop-token b {
    color: var(--text-dim);
    font-weight: 620;
  }

  .prof-module-scope .prof-loop-token strong {
    color: var(--cyan);
    font-family: var(--font-tech);
    font-weight: 780;
  }

  .prof-module-scope .val-highlight { color: var(--gold); font-family: var(--font-tech); }
  .prof-module-scope .val-cyan { color: var(--cyan); font-family: var(--font-tech); }
  .prof-module-scope .val-red { color: var(--red); }
  .prof-module-scope .val-green { color: var(--green); }

  .prof-module-scope .prof-action-zone {
    position: sticky;
    bottom: 0;
    z-index: 5;
    display: grid;
    gap: 8px;
    align-self: end;
    padding: 9px;
    border-radius: 8px;
    border: 1px solid rgba(141, 225, 239, 0.1);
    background:
      radial-gradient(circle at 50% 0%, rgba(141, 225, 239, 0.08), transparent 58%),
      rgba(2, 12, 18, 0.94);
  }

  .prof-module-scope.is-prof-busy .prof-action-zone {
    opacity: 0.62;
    pointer-events: none;
  }

  .prof-module-scope.is-prof-busy .action-btn::after {
    content: ' 执行中…';
    font-weight: 400;
  }

  .prof-module-scope .prof-action-warning {
    min-height: 18px;
    color: var(--red);
    font-size: 0.95em;
    line-height: 1.35;
    text-align: center;
    opacity: 0;
    transform: translateY(2px);
    transition: opacity 0.18s ease, transform 0.18s ease;
  }

  .prof-module-scope .prof-action-warning.is-visible {
    opacity: 1;
    transform: translateY(0);
  }

  .prof-module-scope .action-btn {
    width: 100%;
    align-self: center;
    margin-top: 0;
    background:
      radial-gradient(circle at 50% 0%, rgba(255, 220, 115, 0.4), transparent 38%),
      linear-gradient(90deg, rgba(82, 229, 255, 0.88), rgba(226, 200, 102, 0.72));
    border: 1px solid rgba(241, 219, 128, 0.58);
    color: #07151b;
    padding: 12px 18px;
    border-radius: 999px;
    font-family: var(--font-tech);
    font-size: 1.06em;
    font-weight: 850;
    letter-spacing: 0;
    cursor: pointer;
    text-transform: uppercase;
    transition: transform 0.2s, box-shadow 0.2s, filter 0.2s;
    box-shadow:
      0 0 18px rgba(141, 225, 239, 0.22),
      0 0 28px rgba(226, 200, 102, 0.12),
      inset 0 1px 0 rgba(255, 255, 255, 0.34);
  }
  .prof-module-scope .action-btn:hover:not(:disabled) {
    transform: translateY(-1px);
    filter: saturate(1.12);
    box-shadow:
      0 0 24px rgba(141, 225, 239, 0.32),
      0 0 34px rgba(226, 200, 102, 0.18),
      inset 0 1px 0 rgba(255, 255, 255, 0.42);
    animation: profession-ignition-pulse 1.4s ease-in-out infinite;
  }
  .prof-module-scope .action-btn:disabled {
    background: rgba(255,255,255,0.05);
    border-color: var(--line-soft);
    color: var(--text-dim);
    cursor: not-allowed;
    box-shadow: none;
  }

  @keyframes profession-ignition-pulse {
    0%, 100% { box-shadow: 0 0 18px rgba(141, 225, 239, 0.2), 0 0 24px rgba(226, 200, 102, 0.12), inset 0 1px 0 rgba(255, 255, 255, 0.34); }
    50% { box-shadow: 0 0 30px rgba(141, 225, 239, 0.38), 0 0 42px rgba(226, 200, 102, 0.22), inset 0 1px 0 rgba(255, 255, 255, 0.46); }
  }

  @media (max-width: 720px) {
    .prof-module-scope .prof-workshop-grid {
      grid-template-columns: minmax(0, 1fr);
    }
    .prof-module-scope .prof-workshop-right {
      position: static;
    }
  }

  @media (max-width: 480px) {
    .prof-module-scope .top-status {
      grid-template-columns: 1fr;
    }
    .prof-module-scope .info-panel {
      grid-template-columns: minmax(0, 1fr);
    }
    .prof-module-scope .prof-empty-slots {
      grid-template-columns: repeat(3, minmax(42px, 1fr));
    }
    .prof-module-scope .prof-command-line {
      gap: 8px;
    }
    .prof-module-scope .prof-config-grid,
    .prof-module-scope .prof-workshop-tips,
    .prof-module-scope .prof-preview-summary,
    .prof-module-scope .prof-preview-hero,
    .prof-module-scope .prof-resource-compare {
      grid-template-columns: minmax(0, 1fr);
    }
    .prof-module-scope .param-token--target,
    .prof-module-scope .param-token--materials,
    .prof-module-scope .info-row--wide {
      grid-column: 1 / -1;
    }
    .prof-module-scope .section-card { padding: 10px; }
    .prof-module-scope { --prof-font-base: 10px; }
    .prof-module-scope .section-title { font-size: 1.12em; }
    .prof-module-scope .action-btn { width: 100%; }
  }
`;

