            actionId: actionEvent.actionId,
            sourceActionId: actionEvent.actionId,
            parentNodeId: actionEvent.chainNodeId || '',
            sourceNodeId: actionEvent.chainNodeId || '',
            result: 'hit',
            resultState: 'SUCCESS',
            actionStatus: 'COMPLETED',
